<script setup>
import FormField from './Shared/FormField.vue';
const props = defineProps({ form: Object });
const remove = (index) => {
    const account = props.form.bank_accounts[index];
    if (account.id) props.form.deleted_bank_account_ids.push(account.id);
    props.form.bank_accounts.splice(index, 1);
    props.form.clearErrors();
};
const blank = () => ({ id: null, bank_name: '', account_holder: '', account_number: '', is_active: true });
</script>

<template><div><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-xl font-semibold tracking-tight">Bank accounts</h2><p class="mt-2 max-w-md text-sm leading-6 text-stone-500">Add the accounts customers will use for bank transfers. Payment collection is not available yet.</p></div><button type="button" :disabled="form.bank_accounts.length >= 10" class="rounded-full border border-stone-300 px-4 py-2.5 text-xs font-semibold hover:bg-stone-50 disabled:opacity-50" @click="form.bank_accounts.push(blank())">+ Add account</button></div><p v-if="form.errors.bank_accounts" role="alert" class="mt-3 text-sm text-red-700">{{ form.errors.bank_accounts }}</p><p v-if="form.deleted_bank_account_ids.length" role="status" class="mt-3 text-xs text-stone-500">Removed accounts will be deleted when you save settings.</p><p v-if="form.errors.deleted_bank_account_ids" role="alert" class="mt-3 text-sm text-red-700">{{ form.errors.deleted_bank_account_ids }}</p><div v-if="!form.bank_accounts.length" class="mt-5 rounded-2xl border border-dashed border-stone-300 px-6 py-8 text-center"><p class="text-sm font-medium">No bank accounts yet</p><p class="mt-2 text-xs leading-6 text-stone-500">Add an account when you are ready to accept transfers.</p></div><div v-for="(account, index) in form.bank_accounts" :key="account.id ?? `new-${index}`" class="mt-5 rounded-2xl border border-stone-200 bg-stone-50/50 p-5"><div class="mb-5 flex items-center justify-between"><h3 class="text-sm font-semibold">Account {{ index + 1 }}</h3><button type="button" class="text-xs font-medium text-red-700 underline underline-offset-4 hover:text-red-900" @click="remove(index)">Delete account</button></div><div class="grid gap-5 sm:grid-cols-2"><FormField v-model="account.bank_name" :name="`bank-${index}`" label="Bank name" placeholder="e.g. BCA" required maxlength="100" :error="form.errors[`bank_accounts.${index}.bank_name`]" /><FormField v-model="account.account_holder" :name="`holder-${index}`" label="Account holder" required maxlength="150" :error="form.errors[`bank_accounts.${index}.account_holder`]" /><div class="sm:col-span-2"><FormField v-model="account.account_number" :name="`number-${index}`" label="Account number" required maxlength="40" :error="form.errors[`bank_accounts.${index}.account_number`]" /><p class="mt-2 text-xs text-stone-400">Leading zeros are preserved.</p></div></div><label class="mt-5 flex items-center gap-3 text-sm"><input v-model="account.is_active" type="checkbox" class="size-4 accent-stone-700">Enable this bank account</label><p v-if="form.errors[`bank_accounts.${index}.id`] || form.errors[`bank_accounts.${index}.is_active`]" role="alert" class="mt-2 text-sm text-red-700">{{ form.errors[`bank_accounts.${index}.id`] || form.errors[`bank_accounts.${index}.is_active`] }}</p></div></div></template>
